<div class="page-head"><div><p class="section-kicker">Kitchen operations</p><h1>Production catalog</h1><p>Build verified ingredient and recipe-cost records used by event production sheets. Empty recipes remain team-confirmed instead of receiving invented quantities.</p></div></div>

<div class="form-grid">
<section class="card"><div class="card-heading"><div><h2>Add ingredient</h2><p class="card-subtitle">Cost is stored per selected purchasing or preparation unit.</p></div></div><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="add_ingredient"><label>Name<input name="name" maxlength="190" required></label><div class="form-grid"><label>Unit<input name="unit" maxlength="40" placeholder="lb, oz, each, quart" required></label><label>Cost per unit<input name="cost" inputmode="decimal" pattern="\d+(?:\.\d{1,2})?" value="0.00" required></label></div><label>Supplier <small>optional</small><input name="supplier" maxlength="190"></label><fieldset><legend>Known allergens</legend><?php foreach (\CajunWebPro\Catering\MenuPlanner::ALLERGENS as $key=>$label): ?><label><input type="checkbox" name="allergens[]" value="<?= e_attr($key) ?>"> <?= e($label) ?></label><?php endforeach; ?></fieldset><button class="btn" type="submit">Add ingredient</button></form></section>

<section class="card"><div class="card-heading"><div><h2>Add recipe quantity</h2><p class="card-subtitle">Quantity is the selected ingredient unit required per catered guest.</p></div></div><?php if ($ingredients === []): ?><p class="muted">Add an ingredient first.</p><?php else: ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="add_recipe_ingredient"><label>Menu item<select name="menu_item_id" required><option value="">Choose a dish</option><?php foreach($menuItems as $item): ?><option value="<?= (int)$item['id'] ?>"><?= e($item['name']) ?></option><?php endforeach; ?></select></label><label>Ingredient<select name="ingredient_id" required><option value="">Choose an ingredient</option><?php foreach($ingredients as $ingredient): if(!(int)$ingredient['active'])continue; ?><option value="<?= (int)$ingredient['id'] ?>"><?= e($ingredient['name'].' · '.$ingredient['unit']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Quantity per guest<input name="quantity_per_guest" inputmode="decimal" placeholder="0.1250" required></label><label>Waste allowance %<input name="waste_percent" inputmode="decimal" value="0" required></label><label>Station<input name="station" maxlength="80" value="Kitchen" required></label><label>Prep days before event<input type="number" name="prep_lead_days" min="0" max="365" value="0" required></label></div><label>Container or label note <small>optional</small><input name="label_notes" maxlength="500"></label><label>Preparation notes <small>optional</small><textarea name="prep_notes" rows="4" maxlength="3000"></textarea></label><button class="btn" type="submit">Add to recipe</button></form><?php endif; ?></section>
</div>

<section class="card"><div class="card-heading"><div><h2>Ingredients</h2><p class="card-subtitle">Edit costs as supplier prices change. Deactivation preserves historical recipes.</p></div></div><?php if($ingredients===[]):?><p class="muted">No ingredients configured.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Name / unit</th><th>Cost / supplier</th><th>Allergens</th><th>State</th><th>Save</th></tr></thead><tbody><?php foreach($ingredients as $ingredient): $allergens=json_decode((string)$ingredient['allergens'],true)?:[];$formId='ingredient-'.(int)$ingredient['id']; ?><tr><td><input form="<?=e_attr($formId)?>" aria-label="Ingredient name" name="name" maxlength="190" required value="<?=e_attr($ingredient['name'])?>"><input form="<?=e_attr($formId)?>" aria-label="Ingredient unit" name="unit" maxlength="40" required value="<?=e_attr($ingredient['unit'])?>"></td><td><input form="<?=e_attr($formId)?>" aria-label="Cost per unit" name="cost" inputmode="decimal" required value="<?=e_attr(number_format((int)$ingredient['cost_minor_per_unit']/100,2,'.',''))?>"><input form="<?=e_attr($formId)?>" aria-label="Supplier" name="supplier" maxlength="190" value="<?=e_attr((string)$ingredient['supplier'])?>"></td><td><?php foreach(\CajunWebPro\Catering\MenuPlanner::ALLERGENS as $key=>$label):?><label><input form="<?=e_attr($formId)?>" type="checkbox" name="allergens[]" value="<?=e_attr($key)?>"<?=in_array($key,$allergens,true)?' checked':''?>> <?=e($label)?></label><?php endforeach;?></td><td><label><input form="<?=e_attr($formId)?>" type="checkbox" name="active" value="1"<?=((int)$ingredient['active']===1)?' checked':''?>> Active</label></td><td><form id="<?=e_attr($formId)?>" method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="update_ingredient"><input type="hidden" name="id" value="<?= (int)$ingredient['id'] ?>"><button class="btn secondary" type="submit">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>

<section class="card"><div class="card-heading"><div><h2>Recipe assignments</h2><p class="card-subtitle">Event worksheets scale these quantities and group preparation by station and date.</p></div></div><?php if($recipes===[]):?><p class="muted">No recipe quantities configured.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Dish / ingredient</th><th>Quantity / waste</th><th>Production</th><th>Notes</th><th>Actions</th></tr></thead><tbody><?php foreach($recipes as $recipe):$formId='recipe-'.(int)$recipe['id'];?><tr><td><select form="<?=e_attr($formId)?>" aria-label="Recipe menu item" name="menu_item_id"><?php foreach($menuItems as $item):?><option value="<?= (int)$item['id'] ?>"<?=((int)$recipe['menu_item_id']===(int)$item['id'])?' selected':''?>><?=e($item['name'])?></option><?php endforeach;?></select><select form="<?=e_attr($formId)?>" aria-label="Recipe ingredient" name="ingredient_id"><?php foreach($ingredients as $ingredient):?><option value="<?= (int)$ingredient['id'] ?>"<?=((int)$recipe['ingredient_id']===(int)$ingredient['id'])?' selected':''?>><?=e($ingredient['name'].' · '.$ingredient['unit'])?></option><?php endforeach;?></select></td><td><input form="<?=e_attr($formId)?>" aria-label="Quantity per guest" name="quantity_per_guest" inputmode="decimal" required value="<?=e_attr(rtrim(rtrim(number_format((float)$recipe['quantity_per_guest'],4,'.',''),'0'),'.'))?>"><input form="<?=e_attr($formId)?>" aria-label="Waste percent" name="waste_percent" inputmode="decimal" required value="<?=e_attr(rtrim(rtrim(number_format((float)$recipe['waste_percent'],2,'.',''),'0'),'.'))?>"></td><td><input form="<?=e_attr($formId)?>" aria-label="Station" name="station" maxlength="80" required value="<?=e_attr($recipe['station'])?>"><input form="<?=e_attr($formId)?>" aria-label="Preparation lead days" type="number" name="prep_lead_days" min="0" max="365" required value="<?= (int)$recipe['prep_lead_days'] ?>"></td><td><input form="<?=e_attr($formId)?>" aria-label="Container or label note" name="label_notes" maxlength="500" value="<?=e_attr((string)$recipe['label_notes'])?>"><textarea form="<?=e_attr($formId)?>" aria-label="Preparation notes" name="prep_notes" rows="3" maxlength="3000"><?=e((string)$recipe['prep_notes'])?></textarea></td><td><form id="<?=e_attr($formId)?>" method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="update_recipe_ingredient"><input type="hidden" name="id" value="<?= (int)$recipe['id'] ?>"><button class="btn secondary" type="submit">Save</button><label><input type="checkbox" name="confirm_delete" value="1"> Confirm removal</label><button class="btn danger" type="submit" name="action" value="delete_recipe_ingredient">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>

<section class="card"><div class="card-heading"><div><h2>Upcoming purchasing totals</h2><p class="card-subtitle">Combined ingredient requirements for tentative and confirmed events. Completed and cancelled events are excluded.</p></div></div><?php if($purchasing===[]):?><p class="muted">Add verified recipes to upcoming events to build a purchasing list.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Required</th><th>Events</th><th>Estimated cost</th><th>Allergens</th></tr></thead><tbody><?php foreach($purchasing as $ingredient):?><tr><th scope="row"><?=e($ingredient['name'])?></th><td><?=e(number_format((float)$ingredient['quantity'],3).' '.$ingredient['unit'])?></td><td><?= (int)$ingredient['events'] ?></td><td>$<?=e(number_format((int)$ingredient['cost_minor']/100,2))?></td><td><?=e(implode(', ',json_decode((string)$ingredient['allergens'],true)?:[]))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
